import 'react-native-gesture-handler';
import React from 'react';
import { registerRootComponent } from 'expo';
import App from './App';

// Wrap App with any required providers
function Root() {
  return (
    <React.StrictMode>
      <App />
    </React.StrictMode>
  );
}

// Register the root component
registerRootComponent(Root);
